// Neon Nebula — adapted to this JavaScript Create React App project.
// The remote video is decorative and deliberately has no user controls.
export function AsciiArt({ className = '' }) {
  return (
    <video
      className={className}
      src="https://assets.21st.dev/ascii-recipes/videos/user_3GfKZHMVrEGaZQLVz5Qufduwjfk/b1e07644-b9c3-4bf3-a409-44a1e95759db.mp4"
